1	#!/usr/bin/env node
2	/**
3	 * cli.js —— PID-Bridge 命令行接口（AGH 智能体通过 shell 工具调用本程序）
4	 *
5	 * 子命令：
6	 *   params                              查看当前 last-known-good 参数与配置来源
7	 *   ports                               列出可用串口（硬件模式）
8	 *   set <key> <value>                   下发单个参数（**会先停机**，写完不自动启动）
9	 *   start                               启动平衡（[cmd,Start,1]：复位 PID 后启动）
10	 *   stop                                急停（[cmd,Stop,1]：置 RunFlag=0）
11	 *   rollback                            回滚到 last-known-good（**会先停机**）
12	 *   trial --backend sim|replay|serial   执行一次受控实验并返回指标 JSON
13	 *   selftest                            跑"正常/边界/失败"三类测试样例
14	 *   runs                                列出历史实验索引
15	 *
16	 * 真车实验的时序固定在 backends/serial.js 里：停 → 写参数 → 启动 → 采集 → 停。
17	 * 所有输出（--json 时）都是稳定 JSON，便于智能体解析与留证。
18	 */
19	
20	import { isAbsolute, resolve as presolve } from 'node:path';
21	import { randomUUID, createHash } from 'node:crypto';
22	import { readFileSync } from 'node:fs';
23	import { performance } from 'node:perf_hooks';
24	import {
25	  parseGainList, FIRMWARE_DEFAULTS, TUNABLE, ALLOWED_CMDS,
26	  encodeCmd, encodeSlider, parseTelemetry,
27	} from './lib/protocol.js';
28	import { computeMetrics } from './lib/metrics.js';
29	import { diagnose } from './lib/diagnostics.js';
30	import { loadConfig, costWeights } from './lib/config.js';
31	import { writeRunCsv, appendIndex, readIndex, loadLastGood, saveLastGood, paths } from './lib/store.js';
32	import { runSim, SIM_PRESETS, SIM_MODEL_VERSION } from './backends/sim.js';
33	import { runReplay } from './backends/replay.js';
34	import { elapsedDeviceMs } from './backends/serial.js';
35	
36	const argv = process.argv.slice(2);
37	const cmd = argv[0];
38	const rest = argv.slice(1);
39	const flagErrors = [];
40	const flags = parseFlags(rest);
41	const positional = rest.filter((a) => !a.startsWith('--'));
42	
43	function parseFlags(list) {
44	  const f = {};
45	  for (let i = 0; i < list.length; i++) {
46	    const a = list[i];
47	    if (!a.startsWith('--')) { if (cmd === 'trial') flagErrors.push(`多余的位置参数: ${a}`); continue; }
48	    const key = a.slice(2);
49	    if (Object.hasOwn(f, key)) flagErrors.push(`重复选项: --${key}`);
50	    const next = list[i + 1];
51	    if (['json','help','dry-run'].includes(key)) { f[key] = true; continue; }
52	    if (next === undefined || next.startsWith('--')) { f[key] = true; }
53	    else { f[key] = next; i++; }
54	  }
55	  return f;
56	}
57	
58	const emit = (obj, human) => {
59	  if (flags.json) console.log(JSON.stringify(obj, null, 2));
60	  else console.log(human ?? JSON.stringify(obj, null, 2));
61	};
62	
63	async function main() {
64	  if (flagErrors.length) throw new Error(flagErrors.join('; '));
65	  if (!cmd || flags.help) return usage();
66	
67	  switch (cmd) {
68	    case 'params': return cmdParams();
69	    case 'ports': return cmdPorts();
70	    case 'set': return cmdSet();
71	    case 'start': return cmdStart();
72	    case 'rollback': return cmdRollback();
73	    case 'stop': return cmdStop();
74	    case 'trial': return cmdTrial();
75	    case 'selftest': return cmdSelftest();
76	    case 'runs': return cmdRuns();
77	    default: usage(1);
78	  }
79	}
80	
81	function usage(code = 0) {
82	  console.log(`PID-Bridge —— 平衡车 PID 自动整定实验台
83	
84	用法:
85	  node bridge/cli.js params
86	  node bridge/cli.js ports
87	  node bridge/cli.js set AngleKp 5.5 [--port COM5] [--baud 115200]
88	  node bridge/cli.js start [--port COM5]       # 前台运行并持续发心跳，Ctrl+C 停止
89	  node bridge/cli.js stop [--port COM5]
90	  node bridge/cli.js rollback [--port COM5]
91	  node bridge/cli.js trial --backend sim [--gains "AngleKp=8,AngleKd=7"] [--dur 3000] [--json]
92	  node bridge/cli.js trial --backend replay --csv testdata/sample_step_response.csv --json
93	  node bridge/cli.js trial --backend serial --port COM5 --gains "AngleKp=6" --json
94	  node bridge/cli.js selftest [--json]
95	  node bridge/cli.js runs
96	
97	后端说明:
98	  sim     数字孪生（零依赖，评委无硬件可复现）
99	  replay  回放已采集的 CSV（只读证据通道）
100	  serial  真车（需 npm i serialport）
101	
102	真车安全约定（v2）:
103	  · set / rollback / trial 都会**先停机再写参数**，写完不自动启动（trial 内部会自己启动）
104	  · 一次 trial 的时序固定为：停 → 写参数 → 启动 → 采集 → 停
105	  · 参数只允许改 ${TUNABLE.join(' / ')}（见 lib/protocol.js 的 TUNABLE 白名单）
106	  · 配置来自 configs/bridge.example.json（可被 bridge.local.json / PID_PORT 覆盖），用 params 查看来源`);
107	  process.exit(code);
108	}
109	
110	function cmdParams() {
111	  const { config: cfg, source } = loadConfig();
112	  const good = loadLastGood();
113	  const rows = TUNABLE.map((k) => ({ 参数: k, 固件默认: FIRMWARE_DEFAULTS[k], 'last-known-good': good[k] }));
114	  emit(
115	    { lastGood: good, firmwareDefaults: FIRMWARE_DEFAULTS, tunable: TUNABLE, configSource: source, config: cfg },
116	    `${table(rows)}\n\n可调参数白名单 : ${TUNABLE.join(', ')}\n配置来源       : ${source}\n实验时长默认   : ${cfg.trial.durationMs} ms\n代价权重       : ${JSON.stringify(cfg.cost)}`
117	  );
118	}
119	
120	async function cmdPorts() {
121	  const { listPorts } = await import('./backends/serial.js');
122	  try {
123	    const ports = await listPorts();
124	    emit({ ports }, ports.length ? ports.map((p) => `${p.path}\t${p.manufacturer}`).join('\n') : '未发现串口（检查 CH340 驱动/接线）');
125	  } catch (e) {
126	    emit({ error: e.message }, `错误：${e.message}`);
127	  }
128	}
129	
130	async function cmdSet() {
131	  const [key, value] = positional;
132	  if (!key || value === undefined) usage(1);
133	  const { config: cfg } = loadConfig();
134	  const { sendParams } = await import('./backends/serial.js');
135	  const gains = { [key]: Number(value) };
136	  try {
137	    // sendParams 会先发 [cmd,Stop,1]，写完不自动启动
138	    await sendParams({ port: flags.port ?? cfg.serial.port, baud: Number(flags.baud ?? cfg.serial.baud), gains });
139	    emit(
140	      { ok: true, set: gains, stopped: true },
141	      `已下发 ${key}=${value}\n注意：下发前已自动停机，车现在处于停止状态。需要重新跑车请执行 start。`
142	    );
143	  } catch (e) {
144	    emit({ ok: false, error: e.message }, `失败：${e.message}`);
145	    process.exitCode = 1;
146	  }
147	}
148	
149	async function cmdStart() {
150	  const { config: cfg } = loadConfig();
151	  const { startBalance, waitForSerialStop } = await import('./backends/serial.js');
152	  try {
153	    const session = await startBalance({
154	      port: flags.port ?? cfg.serial.port,
155	      baud: Number(flags.baud ?? cfg.serial.baud),
156	      heartbeatMs: cfg.safety.heartbeatMs,
157	    });
158	    emit({ ok: true, running: true }, '已启动平衡 [cmd,Start,1]（PID 已复位），正在持续发送心跳。按 Ctrl+C 停止。');
159	    const signal = await waitForSerialStop(session);
160	    process.exitCode = signal === 'SIGTERM' ? 143 : 130;
161	  } catch (e) {
162	    emit({ ok: false, error: e.message }, `失败：${e.message}`);
163	    process.exitCode = 1;
164	  }
165	}
166	
167	async function cmdRollback() {
168	  const { config: cfg } = loadConfig();
169	  const good = loadLastGood();
170	  const { sendParams } = await import('./backends/serial.js');
171	  try {
172	    await sendParams({ port: flags.port ?? cfg.serial.port, baud: Number(flags.baud ?? cfg.serial.baud), gains: good });
173	    emit(
174	      { ok: true, rolledBackTo: good, stopped: true },
175	      `已回滚到 last-known-good: ${JSON.stringify(good)}\n注意：回滚前已自动停机，车现在处于停止状态。`
176	    );
177	  } catch (e) {
178	    emit({ ok: false, error: e.message }, `失败：${e.message}`);
179	    process.exitCode = 1;
180	  }
181	}
182	
183	async function cmdStop() {
184	  const { config: cfg } = loadConfig();
185	  const { emergencyStop } = await import('./backends/serial.js');
186	  try {
187	    await emergencyStop({ port: flags.port ?? cfg.serial.port, baud: Number(flags.baud ?? cfg.serial.baud) });
188	    emit({ ok: true, stopped: true }, '已发送急停 [cmd,Stop,1]（连续 5 帧防丢包）');
189	  } catch (e) {
190	    emit({ ok: false, error: e.message }, `失败：${e.message}`);
191	    process.exitCode = 1;
192	  }
193	}
194	
195	async function cmdTrial() {
196	  const { config: cfg, source: cfgSource } = loadConfig();
197	  const backend = flags.backend ?? 'sim';
198	  const durationMs = Number(flags.dur ?? cfg.trial.durationMs);
199	  const target = Number(flags.target ?? 0);
200	  if (!Number.isFinite(durationMs) || durationMs < 1000 || durationMs > 4000)

200	  if (!Number.isFinite(durationMs) || durationMs < 1000 || durationMs > 4000)
201	    throw new Error('trial 时长必须是 1000–4000ms 的有限数字');
202	  if (!Number.isFinite(target)) throw new Error('target 必须是有限数字');
203	  const allowed = ['backend','dur','target','gains','json','x0','seed','disturb','csv','port','baud',
204	    'dry-run','fallLimit','tag','campaign','reason','parent','purpose','plan'];
205	  for (const key of Object.keys(flags)) if (!allowed.includes(key)) throw new Error(`未知 trial 选项: --${key}`);
206	  for (const key of ['backend','dur','target','gains','x0','seed','disturb','csv','port','baud','fallLimit','tag','campaign','reason','parent','purpose','plan'])
207	    if (flags[key] === true) throw new Error(`--${key} 缺少值`);
208	  if (flags.tag && !/^[a-zA-Z0-9_-]{1,80}$/.test(flags.tag)) throw new Error('非法 tag');
209	  if (flags.campaign && !/^[a-zA-Z0-9_-]{1,80}$/.test(flags.campaign)) throw new Error('非法 campaign');
210	  if(backend!=='sim' && (flags.campaign || flags.plan)) throw Error('campaign/plan本轮仅允许sim，不污染其他后端记录');
211	  if (backend === 'replay' && flags.gains !== undefined) throw new Error('replay 为只读，不能指定 --gains');
212	  const fallLimit = Number(flags.fallLimit ?? cfg.metrics.fallLimitDeg);
213	  if (!Number.isFinite(fallLimit) || fallLimit <= 0 || fallLimit > 50) throw new Error('fallLimit 必须在 (0,50] 度');
214	  const good = loadLastGood();
215	  const gains = backend === 'replay' ? null : parseGainList(flags.gains, good);
216	  let experimentPlan=null;
217	  if(flags.plan) {
218	    if(!flags.campaign) throw Error('plan要求campaign');
219	    experimentPlan=JSON.parse(readFileSync(presolve(paths.root,flags.plan),'utf8'));
220	    if(experimentPlan.campaign!==flags.campaign || !Number.isInteger(experimentPlan.maxSearch) ||
221	      experimentPlan.maxSearch<1 || experimentPlan.maxSearch>12 || !Array.isArray(experimentPlan.validation) ||
222	      experimentPlan.validation.length<1 || experimentPlan.validation.length>6 || !experimentPlan.search || !['regulation','impulse-recovery'].includes(experimentPlan.objective) ||
223	      !TUNABLE.every(k=>Array.isArray(experimentPlan.gainRanges?.[k]) && experimentPlan.gainRanges[k].length===2 &&
224	        experimentPlan.gainRanges[k].every(Number.isFinite) && experimentPlan.gainRanges[k][0]<=experimentPlan.gainRanges[k][1]))
225	      throw Error('实验plan非法');
226	  }
227	  if(backend==='sim' && flags.campaign) {
228	    const prior=readIndex().filter(r=>r.campaign===flags.campaign);
229	    const purpose=flags.purpose;
230	    if(!['search','robustness'].includes(purpose) || !flags.reason?.trim()) throw Error('campaign必须指定search/robustness和非空reason');
231	    if(prior.length>=cfg.agents.maxRounds) throw Error('campaign总预算已耗尽');
232	    if(prior.length && prior.at(-1).sourceHash!==sourceHash()) throw Error('源码身份改变，请新建campaign');
233	    if(prior.length ? flags.parent!==prior.at(-1).runId : flags.parent!==undefined) throw Error('parent必须是本campaign上一轮runId，首轮不传parent');
234	    const conditions={durationMs,target,x0:Number(flags.x0??3),seed:Number(flags.seed??20261008),disturbance:flags.disturb?Number(flags.disturb):null};
235	    const conditionOf=r=>({durationMs:r.durationMs,target:r.target,x0:r.meta.sim.x0,seed:r.meta.sim.seed,disturbance:r.meta.sim.disturbance});
236	    const search=prior.filter(r=>r.decision.purpose==='search');
237	    if(prior.length && JSON.stringify(experimentPlan)!==JSON.stringify(prior[0].experimentPlan)) throw Error('plan改变，请新建campaign');
238	    if(experimentPlan) {
239	      const validations=prior.filter(r=>r.decision.purpose==='robustness');
240	      if(purpose==='search' && (search.length>=experimentPlan.maxSearch || validations.length)) throw Error('搜索预算耗尽或已冻结候选');
241	      const expected=purpose==='search'?experimentPlan.search:experimentPlan.validation[validations.length];
242	      if(!expected || JSON.stringify(conditions)!==JSON.stringify(expected)) throw Error('试验条件不符合预先声明plan');
243	      for(const k of TUNABLE) {
244	        const bounds=experimentPlan.gainRanges?.[k];
245	        if(!Array.isArray(bounds)||bounds.length!==2||!bounds.every(Number.isFinite)||gains[k]<bounds[0]||gains[k]>bounds[1]) throw Error('参数超出plan范围');
246	      }
247	      if(validations.length && JSON.stringify(gains)!==JSON.stringify(validations[0].gains)) throw Error('验证阶段候选已冻结');
248	      if(purpose==='robustness' && !search.some(r=>!r.metrics.fail && JSON.stringify(r.gains)===JSON.stringify(gains))) throw Error('验证候选必须来自已测非摔倒搜索点');
249	    }
250	    if(purpose==='search' && search.length && (JSON.stringify(conditions)!==JSON.stringify(conditionOf(search[0])) ||
251	      JSON.stringify({...cfg.metrics,fallLimitDeg:fallLimit})!==JSON.stringify(search[0].evaluation.metrics) ||
252	      JSON.stringify(costWeights(cfg))!==JSON.stringify(search[0].evaluation.weights))) throw Error('搜索条件或评价配置改变，请新建campaign');
253	    const signature=g=>TUNABLE.map(k=>g[k]);
254	    if(prior.some(r=>JSON.stringify(signature(r.gains))===JSON.stringify(signature(gains)) &&
255	      JSON.stringify(conditionOf(r))===JSON.stringify(conditions))) throw Error('campaign已有相同参数和条件，不重复试验');
256	  }
257	  const started = performance.now();
258	
259	  let samples = [];
260	  let meta = { backend, durationMs, target, configSource: cfgSource };
261	
262	  if (backend === 'sim') {
263	    samples = runSim({
264	      gains, target, durationMs,
265	      x0: Number(flags.x0 ?? 3),
266	      seed: Number(flags.seed ?? 20261008),
267	      disturbance: flags.disturb
268	        ? { atMs: Math.floor(durationMs * 0.5), impulseDegPerSec: Number(flags.disturb) }
269	        : null,
270	    });
271	    meta.sim = { modelVersion:SIM_MODEL_VERSION,controlDtMs:10,sampleMs:50,
272	      timeSemantics:'state-at-t; output held on [t,t+dt); terminal output held from prior interval',x0: Number(flags.x0 ?? 3), seed: Number(flags.seed ?? 20261008),
273	      disturbance: flags.disturb ? Number(flags.disturb) : null,
274	      disturbanceEvent:flags.disturb?{type:'angular-velocity-impulse',atMs:Math.floor(durationMs*0.5),
275	        amplitude:Number(flags.disturb),unit:'deg/s'}:null,termination: samples.termination };
276	  } else if (backend === 'replay') {
277	    if (!flags.csv) throw new Error('replay 后端需要 --csv <文件>');
278	    const file = isAbsolute(flags.csv) ? flags.csv : presolve(paths.root, flags.csv);
279	      samples = runReplay({ file });
280	    meta.csv = file;
281	    meta.requestedTarget = target;
282	    meta.requestedDurationMs = durationMs;
283	    meta.target = samples[0]?.target ?? null;
284	    meta.durationMs = samples.length ? samples.at(-1).ms - samples[0].ms : 0;
285	  } else if (backend === 'serial') {
286	    const serialPort = flags.port ?? cfg.serial.port;
287	    if (!serialPort) throw new Error('serial 后端没有可用串口：请配置 serial.port 或传 --port COMx');
288	    if (flags['dry-run']) {
289	      samples = [];
290	      meta.dryRun = true;
291	      meta.port = serialPort;
292	    } else {
293	      const { runSerial, sendParams } = await import('./backends/serial.js');
294	      const r = await runSerial({
295	        port: serialPort,
296	        baud: Number(flags.baud ?? cfg.serial.baud),
297	        gains,
298	        durationMs,
299	        heartbeatMs: cfg.safety.heartbeatMs,
300	        settleMs: cfg.safety.settleMs,
301	      });
302	      samples = r.samples;
303	      meta.timedOut = r.timedOut;
304	      meta.port = serialPort;
305	      meta.interrupted = r.interrupted;
306	      if (r.interrupted) process.exitCode = r.signal === 'SIGTERM' ? 143 : 130;
307	      if (r.timedOut || samples.length === 0) {
308	        // 采集失败 → 回到已知可用参数，避免车停在未知状态
309	        await sendParams({ port: serialPort, baud: Number(flags.baud ?? cfg.serial.baud), gains: good })
310	          .then(() => { meta.rolledBack = true; })
311	          .catch(e => { meta.rolledBack = false; meta.rollbackError = e.message; });
312	      }
313	    }
314	  } else {
315	    throw new Error(`未知后端: ${backend}`);
316	  }
317	
318	  const metrics = computeMetrics(samples, {
319	    ...cfg.metrics,
320	    termination: meta.sim?.termination,
321	    fallLimitDeg: fallLimit,
322	    weights: costWeights(cfg),
323	  });
324	
325	  // ⚠️ 安全语义：只有**真车验证过**的收敛参数才允许提升为 last-known-good。
326	  //    仿真/回放里"跑得好"不等于真车安全 —— 绝不能把仿真参数当成真车的回滚目标。
327	  const hardwareVerified = backend === 'serial' && !meta.dryRun && !meta.interrupted && !meta.timedOut;
328	  const promoted = metrics.ok && metrics.converged && hardwareVerified;
329	  if (promoted) saveLastGood(gains);
330	
331	  const csvName = samples.length ? writeRunCsv(flags.tag ?? backend, samples) : null;
332	  const record = {
333	    runId: randomUUID(),
334	    ts: new Date().toISOString(),
335	    backend, gains, target: meta.target, durationMs: meta.durationMs, csv: csvName,
336	    csvHash: csvName ? createHash('sha256').update(readFileSync(presolve(paths.runs, csvName))).digest('hex') : null,
337	    campaign: flags.campaign ?? null,
338	    decision: { reason: flags.reason ?? null, parent: flags.parent ?? null, purpose: flags.purpose ?? 'unspecified' },
339	    experimentPlan,
340	    evaluation: { version: '2.3', metrics: { ...cfg.metrics, fallLimitDeg: fallLimit }, weights: costWeights(cfg) },
341	    sourceHash: sourceHash(),
342	    meta,
343	    wallMs: Math.max(0, Math.round(performance.now() - started)),
344	    metrics: sampleSafe(metrics),
345	    diagnostics: backend==='sim' && samples.length>=2 ? diagnose(samples,{tolerance:metrics.tol??cfg.metrics.tolFloor,
346	      holdMs:cfg.metrics.settleHoldMs,disturbanceAtMs:meta.sim.disturbanceEvent?.atMs??null}) : null,
347	  };
348	  appendIndex(record);
349	
350	  const verdict = metrics.fail ? '失败' : metrics.converged ? '收敛' : '未收敛';
351	  const human = [
352	    `后端      : ${backend}${meta.csv ? ' (' + meta.csv + ')' : ''}${meta.port ? '  串口: ' + meta.port : ''}   配置来源: ${cfgSource}`,
353	    `参数      : ${JSON.stringify(gains)}  (来源: ${flags.gains ? '命令行' : 'last-known-good'})`,
354	    `判定      : ${verdict}`,
355	    `超调      : ${fmt(metrics.overshoot)}  调节时间: ${fmt(metrics.settlingMs)} ms  稳态误差: ${fmt(metrics.ssErr)}`,
356	    `振荡次数  : ${fmt(metrics.osc)}   控制能量: ${fmt(metrics.energy)}   J: ${fmt(metrics.j)}`,
357	    `参数提升  : ${promoted ? '已写入 last-known-good（真车验证）' : hardwareVerified ? '否（未收敛，保留原值）' : '否（非真车后端，不提升为回滚目标）'}`,
358	    `原始数据  : runs/${csvName ?? '(无)'}`,
359	  ].join('\n');
360	
361	  emit({ ...record, verdict: metrics.converged ? 'converged' : metrics.fail ? 'failed' : 'not_converged' }, human);
362	}
363	
364	async function cmdSelftest() {
365	  // v2：自检也走配置文件，保证"自检通过的值"与"真跑时的值"是同一套口径
366	  const { config: cfg, source: cfgSource } = loadConfig();
367	  const metricOpts = { ...cfg.metrics, weights: costWeights(cfg) };
368	
369	  const cases = [];
370	  const protocolChecks = {};
371	  try {
372	    for (const action of ALLOWED_CMDS) {
373	      protocolChecks[`cmd:${action}`] = encodeCmd(action) === `[cmd,${action},1]`;
374	    }
375	    protocolChecks['slider:clamp'] = encodeSlider('AngleKp', 999).frame === '[slider,AngleKp,20]';
376	    protocolChecks['telemetry:parse'] = parseTelemetry('T,123,1.2,0,3,4,5,6')?.ms === 123;
377	    protocolChecks['device-tick:wrap'] = elapsedDeviceMs(2, 0xFFFFFFFE) === 4;
378	  } catch {
379	    for (const action of ALLOWED_CMDS) protocolChecks[`cmd:${action}`] = false;
380	    protocolChecks['slider:clamp'] = false;
381	    protocolChecks['telemetry:parse'] = false;
382	    protocolChecks['device-tick:wrap'] = false;
383	  }
384	  const protocolPass = Object.values(protocolChecks).every(Boolean);
385	  for (const [key, preset] of Object.entries(SIM_PRESETS)) {
386	    const samples = runSim({ gains: preset.gains, durationMs: cfg.trial.durationMs });
387	    const m = computeMetrics(samples, metricOpts);
388	    cases.push({ key, label: preset.label, gains: preset.gains, metrics: sampleSafe(m) });
389	  }
390	
391	  // 回放样例（若存在示例 CSV）
392	  try {
