396	      label: '回放：示例数据集（合成数据，非真实实验）',
397	      gains: null,
398	      metrics: sampleSafe(computeMetrics(samples, metricOpts)),
399	    });
400	  } catch (e) {
401	    cases.push({ key: 'replay-sample', label: `回放跳过：${e.message}`, metrics: null });
402	  }
403	
404	  const expect = {
405	    // 正常类：应当收敛
406	    'normal-tuned': (m) => m && !m.fail && m.converged,
407	    'normal-conservative': (m) => m && !m.fail && m.converged,
408	    // 边界类：不摔倒、指标可计算即可（允许性能一般）
409	    'boundary-high-kd': (m) => m && !m.fail,
