419	  const rows = cases.map((c) => {
420	    const pass = expect[c.key] ? expect[c.key](c.metrics) : true;
421	    return {
422	      样例: c.key,
423	      说明: c.label,
424	      判定: pass ? 'PASS' : 'FAIL',
425	      收敛: c.metrics ? (c.metrics.fail ? '摔倒/失败' : c.metrics.converged ? '是' : '否') : '-',
