433	  const allPass = protocolPass && rows.every((r) => r.判定 === 'PASS');
434	  await Promise.resolve(); // 保持 async 形状
435	  if (flags.out) {
436	    const { writeFileSync, mkdirSync } = await import('node:fs');
437	    const { dirname } = await import('node:path');
438	    mkdirSync(dirname(flags.out), { recursive: true });
439	    writeFileSync(flags.out, JSON.stringify({ ts: new Date().toISOString(), allPass, protocol: protocolChecks, cases }, null, 2), 'utf8');
440	  }
441	  emit(
442	    { allPass, protocol: protocolChecks, cases },
443	    `${table(rows)}\n\n协议自检: ${protocolPass ? 'PASS' : 'FAIL'} (${Object.entries(protocolChecks).map(([k, v]) => `${k}=${v ? 'PASS' : 'FAIL'}`).join(', ')})\n总体: ${allPass ? 'PASS —— 协议与正常/边界/失败样例均符合预期' : 'FAIL —— 存在不符合预期的样例'}`
444	  );
445	  if (!allPass) process.exitCode = 1;
446	}
